// Procesar cada lead secuencialmente con delay
const items = $input.all();
const results = [];

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

for (let i = 0; i < items.length; i++) {
  const lead = items[i].json;

  try {
    // Enviar WhatsApp
    const waResponse = await fetch('https://graph.facebook.com/v22.0/946501128543201/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + $env.WHATSAPP_TOKEN
      },
      body: JSON.stringify({
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: lead.phone,
        type: 'interactive',
        interactive: {
          type: 'button',
          body: {
            text: `📅 *Recordatorio - Tu cita es mañana*\n\nHola ${lead.name}, te recordamos que tienes una reunión agendada con AutomatizaTech.\n\n📅 *Fecha:* ${lead.scheduled_date}\n🕐 *Hora:* ${lead.scheduled_time} hrs\n📍 *Enlace:* ${lead.meet_link || 'Te llegará por correo'}\n\n¿Podrás asistir?`
          },
          action: {
            buttons: [
              { type: 'reply', reply: { id: `btn_reminder_confirm_${lead.id}`, title: '✅ Sí, confirmo' }},
              { type: 'reply', reply: { id: `btn_reminder_no_${lead.id}`, title: '❌ No podré' }}
            ]
          }
        }
      })
    });

    const waResult = await waResponse.json();

    // Marcar como enviado
    const markResponse = await fetch(`https://automatizatech.cl/wp-json/automatiza-tech/v1/leads/update-reminder/${lead.id}/24h`, {
      method: 'POST'
    });

    results.push({
      json: {
        lead_id: lead.id,
        name: lead.name,
        phone: lead.phone,
        whatsapp_sent: waResponse.ok,
        marked_sent: markResponse.ok,
        wa_response: waResult
      }
    });

    // Esperar 5 segundos antes del siguiente (excepto el último)
    if (i < items.length - 1) {
      await sleep(5000);
    }

  } catch (error) {
    results.push({
      json: {
        lead_id: lead.id,
        name: lead.name,
        error: error.message
      }
    });
  }
}

return results;
